13	new file mode 100644
14	index 0000000..14db788
15	--- /dev/null
16	+++ b/src/explore/stroll/motion.ts
17	@@ -0,0 +1,116 @@
18	+/* ============================ Đi dạo: chuyển động nhân vật (thuần) ============================
19	+   Mỗi khung: đọc đầu vào, đổi tốc độ / hướng mặt, nhảy, đi qua stMove (va chạm), bám cao độ đứng, chọn dáng (pose).
20	+   Thuần: không import three, không đụng DOM. stStep chạy mỗi khung nên không cấp phát (D-018): dùng đối tượng tạm cấp module.
21	+   - dt kẹp về dtMax: khung rất dài (tab ẩn rồi quay lại) không làm nhân vật vọt qua tường, chỉ chậm đi một khung.
22	+   - Hướng: tới = (cos yaw, 0, −sin yaw), yaw tăng là quay trái (như flight.ts).
23	+   - Cổng nhịp quay đóng dưới chân (vị trí không còn hợp lệ): stMove đóng băng khi điểm xuất phát không hợp lệ, nên sơ tán KHÔNG dùng stMove:
24	+     tính một lần điểm hợp lệ gần nhất (stNearestValid, đắt), rồi đi thẳng tới đó với tốc độ chạy, bỏ qua đầu vào; tới nơi thì trả điều khiển. */
25	+import { CONFIG } from '../../config';
26	+import { stMove, stValid, stGroundY, stNearestValid, type StMap } from './map';
27	+import { stSpawn } from './mapData';
28	+
29	+export const ST_POSE_IDLE = 0, ST_POSE_WALK = 1, ST_POSE_RUN = 2, ST_POSE_JUMP = 3, ST_POSE_PHOTO = 4;
30	+
31	+export interface StState {
32	+  x: number; y: number; z: number;   // y: cao độ chân tuyệt đối, m
33	+  yaw: number; speed: number;        // speed: tốc độ mặt bằng, m/s
34	+  vy: number; air: boolean;          // vy: vận tốc đứng, m/s
35	+  pose: number; evac: boolean;
36	+  photo: number;                     // giây còn giơ tay chụp
37	+  tx: number; tz: number;            // điểm sơ tán đã tính (chỉ có nghĩa khi evac)
38	+}
39	+export interface StInput { mx: number; mz: number; run: boolean; jump: boolean; camYaw: number }
40	+
41	+const EPS_STEP = 1e-3;      // dung sai khi so bậc cao độ với stepMax (bậc Cầu Rồng lề ↔ bờ đo 0,3500083), m
42	+const V_STOP = 0.1;         // m/s — dưới mức này coi là đứng yên
43	+const _mv = { x: 0, z: 0 };      // kết quả stMove
44	+const _near = { x: 0, z: 0 };    // kết quả stNearestValid
45	+
46	+export function stCreate(map: StMap, slot: number): StState {
47	+  const p = { x: 0, z: 0 };
48	+  stSpawn(map, slot, p);
49	+  const g = stGroundY(map, p.x, p.z);
50	+  return { x: p.x, y: g === g ? g : CONFIG.roadY, z: p.z, yaw: CONFIG.stroll.spawnYaw, speed: 0, vy: 0, air: false, pose: ST_POSE_IDLE, evac: false, photo: 0, tx: p.x, tz: p.z };
51	+}
52	+
53	+export function stPhotoPose(s: StState): void { s.photo = CONFIG.stroll.photoHold; }
54	+
55	+/* quay yaw về đích theo đường ngắn nhất, tốc độ mũ turn (1/s) */
56	+function stTurn(yaw: number, target: number, turn: number, dt: number): number {
57	+  let d = (target - yaw) % (2 * Math.PI);
58	+  if (d > Math.PI) d -= 2 * Math.PI; else if (d < -Math.PI) d += 2 * Math.PI;
59	+  const k = turn * dt;
60	+  return yaw + d * (k < 1 ? k : 1);
61	+}
62	+
63	+/* Sơ tán: đi thẳng tới (tx, tz) với tốc độ chạy, mỗi khung không quá run × dt */
64	+function stEvacStep(s: StState, map: StMap, dt: number): void {
65	+  const C = CONFIG.stroll, dx = s.tx - s.x, dz = s.tz - s.z, dist = Math.sqrt(dx * dx + dz * dz), step = C.run * dt;
66	+  s.photo = 0; s.speed = C.run; s.pose = ST_POSE_RUN;
67	+  if (dist > 1e-9) s.yaw = stTurn(s.yaw, Math.atan2(-dz, dx), C.turn, dt);
68	+  if (dist <= step) { s.x = s.tx; s.z = s.tz; s.evac = false; s.speed = 0; s.pose = ST_POSE_IDLE; }
69	+  else { s.x += dx / dist * step; s.z += dz / dist * step; }
70	+  const g = stGroundY(map, s.x, s.z);
71	+  if (g === g) s.y = g;                                  // ngoài mọi vùng (cổng đóng): giữ cao độ cũ
72	+  s.air = false; s.vy = 0;
73	+}
74	+
75	+export function stStep(s: StState, inp: StInput, map: StMap, dt: number): void {
76	+  const C = CONFIG.stroll;
77	+  if (!(dt > 0)) return;
78	+  if (dt > C.dtMax) dt = C.dtMax;
79	+
80	+  /* 1) vị trí không còn hợp lệ với tường cao / vùng (tường thấp không tính: đáp xuống giữa tường thấp là chuyện của stMove) */
81	+  if (!s.evac && !stValid(map, s.x, s.z, Infinity)) {
82	+    s.evac = true;
83	+    if (!stNearestValid(map, s.x, s.z, _near)) stSpawn(map, -1, _near);
84	+    s.tx = _near.x; s.tz = _near.z;
85	+  }
86	+  if (s.evac) { stEvacStep(s, map, dt); return; }
87	+
88	+  /* 2) hướng đi và tốc độ đích */
89	+  const sc = Math.sin(inp.camYaw), cc = Math.cos(inp.camYaw);
90	+  const dx = inp.mz * cc + inp.mx * sc, dz = -inp.mz * sc + inp.mx * cc;
91	+  let len = Math.sqrt(dx * dx + dz * dz);
92	+  const moving = len > 1e-6;
93	+  if (len > 1) len = 1;
94	+  const target = moving ? (inp.run ? C.run : C.walk) * len : 0;
95	+  const da = C.accel * dt;
96	+  if (s.speed < target) s.speed = s.speed + da < target ? s.speed + da : target;
97	+  else s.speed = s.speed - da > target ? s.speed - da : target;
98	+  let hx: number, hz: number;                            // hướng di chuyển: theo đầu vào; thả tay thì trượt theo hướng mặt đang hãm
99	+  if (moving) { hx = dx / Math.sqrt(dx * dx + dz * dz); hz = dz / Math.sqrt(dx * dx + dz * dz); s.yaw = stTurn(s.yaw, Math.atan2(-hz, hx), C.turn, dt); }
100	+  else { hx = Math.cos(s.yaw); hz = -Math.sin(s.yaw); }
101	+
102	+  /* 3) nhảy: chỉ khi chạm đất */
103	+  if (!s.air && inp.jump) { s.vy = Math.sqrt(2 * C.gravity * C.jumpHeight); s.air = true; }
104	+
105	+  /* 4) đi (feet: độ cao chân trên cao độ đứng chỗ đang đứng) */
106	+  const g0 = stGroundY(map, s.x, s.z);
107	+  const feet = s.air && g0 === g0 ? Math.max(0, s.y - g0) : 0;
108	+  const dist = s.speed * dt;
109	+  stMove(map, s.x, s.z, hx * dist, hz * dist, feet, _mv);
110	+  s.x = _mv.x; s.z = _mv.z;
111	+
112	+  /* 5) cao độ */
113	+  const g = stGroundY(map, s.x, s.z);
114	+  if (s.air) {
115	+    const ny = s.y + s.vy * dt - 0.5 * C.gravity * dt * dt;
116	+    s.vy -= C.gravity * dt;
117	+    if (g === g && ny <= g) {                            // chạm đất
118	+      s.y = g; s.vy = 0; s.air = false;
119	+      if (!stValid(map, s.x, s.z, 0) && stNearestValid(map, s.x, s.z, _near)) { s.x = _near.x; s.z = _near.z; const g2 = stGroundY(map, s.x, s.z); if (g2 === g2) s.y = g2; }   // đáp giữa tường thấp: đẩy ra mép gần nhất
120	+    } else s.y = ny;
121	+  } else if (g === g) {
122	+    if (s.y - g > C.stepMax + EPS_STEP) { s.air = true; s.vy = 0; }   // bước xuống quá bậc: rơi
123	+    else s.y = g;
124	+  }
125	+
126	+  /* 6) dáng */
127	+  if (s.photo > 0) { if (moving || s.air) s.photo = 0; else { s.photo -= dt; if (s.photo < 0) s.photo = 0; } }
128	+  const still = s.speed < V_STOP && !moving;
129	+  if (s.air) s.pose = ST_POSE_JUMP;
130	+  else if (s.photo > 0 && still) s.pose = ST_POSE_PHOTO;
131	+  else if (s.speed < V_STOP) s.pose = ST_POSE_IDLE;
132	+  else s.pose = s.speed > (C.walk + C.run) * 0.5 ? ST_POSE_RUN : ST_POSE_WALK;
133	+}
134	diff --git a/tests/stroll-unit/motion.test.ts b/tests/stroll-unit/motion.test.ts
135	new file mode 100644
136	index 0000000..e859f4a
137	--- /dev/null
138	+++ b/tests/stroll-unit/motion.test.ts
139	@@ -0,0 +1,219 @@
140	+/* ===== Đi dạo: test chuyển động nhân vật (src/explore/stroll/motion.ts) =====
141	+   Bản đồ thật (stBuildStaticMap) cộng 300 nhà chữ nhật giả sinh bằng rng trong hai vùng bờ. Fuzz 300 000 khung kiểm điểm cuối bằng oracle viết riêng ở đây
142	+   (quét tuyến tính mọi vùng / vật cản cao, không dùng lưới của map.ts). */
143	+import { test } from 'node:test';
144	+import assert from 'node:assert/strict';
145	+import { CONFIG } from '../../src/config.ts';
146	+import { rng } from '../../src/common/math.ts';
147	+import { deckY } from '../../src/bridges/dragon/profile.ts';
148	+import { SH } from '../../src/bridges/song-han/profile.ts';
149	+import { stValid, stSetGate, stAddSolids, stGroundY, type StMap, type StSolid } from '../../src/explore/stroll/map.ts';
150	+import { ST_GATE_SWING, stBuildStaticMap, stSpawn } from '../../src/explore/stroll/mapData.ts';
151	+import { stCreate, stStep, stPhotoPose, type StState, type StInput } from '../../src/explore/stroll/motion.ts';
152	+
153	+const C = CONFIG.stroll, R = C.radius, SHZ = CONFIG.songHan.z;
154	+const DT = 1 / 60;
155	+
156	+/* bản đồ có nhà giả: mỗi lần gọi dựng mới (cổng đóng / mở không dây sang test khác) */
157	+function makeMap(): StMap {
158	+  const map = stBuildStaticMap();
159	+  const r = rng(4242), sp = { x: 0, z: 0 }, houses: StSolid[] = [];
160	+  stSpawn(map, -1, sp);
161	+  for (let i = 0; i < 300; i++) {
162	+    const west = r() < 0.5, x0 = (west ? -1 : 1) * (270 + r() * 120), z0 = -1290 + r() * 1500, w = 8 + r() * 30, d = 8 + r() * 30;
163	+    const h: StSolid = { kind: 'rect', x0: west ? x0 - w : x0, x1: west ? x0 : x0 + w, z0, z1: z0 + d };
164	+    if (h.z1 > -22 && h.z0 < 22 || h.z1 > SHZ - 10 && h.z0 < SHZ + 10) continue;   // nhà thật không đè đường nối cầu
165	+    if (sp.x > h.x0 - 3 && sp.x < h.x1 + 3 && sp.z > h.z0 - 3 && sp.z < h.z1 + 3) continue;   // bỏ nhà đè điểm xuất phát
166	+    houses.push(h);
167	+  }
168	+  stAddSolids(map, houses);
169	+  return map;
170	+}
171	+const IDLE: StInput = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };
172	+const inp = (o: Partial<StInput>): StInput => ({ ...IDLE, ...o });
173	+function at(map: StMap, x: number, z: number): StState {
174	+  const s = stCreate(map, -1); s.x = x; s.z = z; s.y = stGroundY(map, x, z); return s;
175	+}
176	+
177	+test('đi thẳng 10 s: đi 3,5 m/s, chạy 10 m/s', () => {
178	+  for (const run of [false, true]) {
179	+    const map = makeMap(), s = stCreate(map, -1), x0 = s.x;
180	+    for (let i = 0; i < 600; i++) stStep(s, inp({ mz: 1, run }), map, DT);
181	+    const v = run ? C.run : C.walk;
182	+    assert.ok(Math.abs(s.speed - v) <= (run ? 0.1 : 0.05), `tốc độ ${s.speed}`);
183	+    assert.ok(Math.abs(s.x - x0 - 10 * v) <= (run ? 2 : 1.5), `quãng đường ${s.x - x0}`);
184	+  }
185	+});
186	+
187	+test('hướng theo camYaw', () => {
188	+  const map = makeMap();
189	+  let s = at(map, 0, 17.4);
190	+  for (let i = 0; i < 30; i++) stStep(s, inp({ mz: 1, camYaw: 0 }), map, DT);
191	+  assert.ok(s.x > 1 && Math.abs(s.z - 17.4) < 0.01, 'camYaw 0, tới → x tăng');
192	+  s = at(map, 0, 0 + 3.5);   // dải phân cách có thân rồng chỉ ở đầu / cuối: x = 0 trống
193	+  const z0 = s.z;
194	+  for (let i = 0; i < 30; i++) stStep(s, inp({ mz: 1, camYaw: Math.PI / 2 }), map, DT);
195	+  assert.ok(s.z < z0 - 1, 'camYaw π/2, tới → z giảm');
196	+  s = at(map, 0, 17.4); const z1 = s.z;
197	+  for (let i = 0; i < 30; i++) stStep(s, inp({ mx: 1, camYaw: 0 }), map, DT);
198	+  assert.ok(s.z > z1 + 0.1, 'camYaw 0, sang phải → z tăng (lề hẹp, bị lan can chặn)');
199	+  s = at(map, 0, 5); const z2 = s.z;
200	+  for (let i = 0; i < 30; i++) stStep(s, inp({ mx: 1, camYaw: 0 }), map, DT);
201	+  assert.ok(s.z > z2 + 1, 'camYaw 0, sang phải → z tăng (chỗ rộng)');
202	+});
203	+
204	+test('nhảy: đỉnh 1,2 m, pose 3 trên không, giữ nút không nhảy lần hai', () => {
205	+  const map = makeMap(), s = at(map, 0, 5), g = s.y;
206	+  let peak = 0, airFrames = 0, landed = -1;
207	+  for (let i = 0; i < 120; i++) {
208	+    stStep(s, inp({ jump: true }), map, 1 / 120);
209	+    peak = Math.max(peak, s.y - g);
210	+    if (s.air) { airFrames++; assert.equal(s.pose, 3); }
211	+    else if (landed < 0 && i > 2) landed = i;
212	+  }
213	+  assert.ok(Math.abs(peak - C.jumpHeight) <= 0.05, `đỉnh ${peak}`);
214	+  assert.ok(airFrames > 0);
215	+  /* một cú nhảy: thời gian bay = 2 v / g ≈ 0,69 s = 83 khung; sau đó (còn giữ) mới nhảy lần nữa, không có đỉnh thứ hai trước khi chạm */
216	+  const s2 = at(map, 0, 5); let rises = 0, prevVy = 0, hit = false;
217	+  for (let i = 0; i < 80; i++) {
218	+    stStep(s2, inp({ jump: true }), map, 1 / 120);
219	+    if (s2.vy > prevVy + 1e-9) rises++;
220	+    prevVy = s2.vy; if (!s2.air) hit = true;
221	+  }
222	+  assert.equal(rises, 1, 'vy chỉ tăng đúng một lần (lúc bật)');
223	+  assert.ok(!hit, 'chưa chạm đất trong 80 khung 1/120 s');
224	+});
225	+
226	+test('cao độ: đi dọc Cầu Rồng bám mặt cầu + bậc', () => {
227	+  const map = makeMap(), s = at(map, -300, 17.4);
228	+  let worst = 0, minx = s.x;
229	+  for (let i = 0; i < 6000 && s.x < 300; i++) {
230	+    stStep(s, inp({ mz: 1, run: true }), map, DT);
231	+    const ground = stGroundY(map, s.x, s.z);
232	+    worst = Math.max(worst, Math.abs(s.y - ground));
233	+    assert.ok(Math.abs(s.y - (deckY(s.x) + (Math.abs(s.z) <= 3 ? 0.3 : Math.abs(s.z) < 16.075 ? 0.02 : 0.25))) <= 0.02, `x=${s.x}`);
234	+  }
235	+  assert.ok(s.x >= 300, `đi tới x ${s.x}`);
236	+  assert.ok(worst <= 0.02);
237	+});
238	+
239	+test('pose: 0 đứng, 1 đi, 2 chạy, 4 chụp ảnh rồi hết photoHold về 0', () => {
240	+  const map = makeMap(), s = at(map, 0, 17.4);
241	+  stStep(s, IDLE, map, DT); assert.equal(s.pose, 0);
242	+  for (let i = 0; i < 40; i++) stStep(s, inp({ mz: 1 }), map, DT);
243	+  assert.equal(s.pose, 1);
244	+  for (let i = 0; i < 60; i++) stStep(s, inp({ mz: 1, run: true }), map, DT);
245	+  assert.equal(s.pose, 2);
246	+  for (let i = 0; i < 60; i++) stStep(s, IDLE, map, DT);
247	+  assert.equal(s.pose, 0);
248	+  stPhotoPose(s); assert.equal(s.photo, C.photoHold);
249	+  stStep(s, IDLE, map, DT); assert.equal(s.pose, 4);
250	+  for (let i = 0; i < Math.ceil(C.photoHold / DT) + 2; i++) stStep(s, IDLE, map, DT);
251	+  assert.equal(s.pose, 0); assert.equal(s.photo, 0);
252	+});
253	+
254	+test('dt = 2 s lúc chạy vào lan can Cầu Rồng: không vọt xa, không lọt', () => {
255	+  const map = makeMap(), s = at(map, 0, 17.4);
256	+  for (let i = 0; i < 60; i++) stStep(s, inp({ mx: 1, run: true, camYaw: 0 }), map, DT);   // chạy sang phải = +z, tới lan can phía Nam
257	+  const before = { x: s.x, z: s.z };
258	+  stStep(s, inp({ mx: 1, run: true }), map, 2);
259	+  assert.ok(Math.hypot(s.x - before.x, s.z - before.z) <= C.run * C.dtMax + 0.01);
260	+  assert.ok(stValid(map, s.x, s.z, 0));
261	+  /* chạy thẳng dọc, rồi một khung 2 s đâm vào mép đầu cầu: vẫn hợp lệ */
262	+  const t = at(map, 0, 17.4);
263	+  for (let i = 0; i < 90; i++) stStep(t, inp({ mz: 1, run: true, camYaw: 0 }), map, DT);
264	+  for (let k = 0; k < 5; k++) { const p = { x: t.x, z: t.z }; stStep(t, inp({ mz: 1, mx: 1, run: true, camYaw: 0 }), map, 2); assert.ok(Math.hypot(t.x - p.x, t.z - p.z) <= C.run * C.dtMax + 0.01); assert.ok(stValid(map, t.x, t.z, Infinity)); }
265	+});
266	+
267	+test('gờ chắn xe Cầu Rồng: đi ngang bị chặn, chạy + nhảy thì qua', () => {
268	+  const map = makeMap();
269	+  /* từ lề Nam (z 17,4) đi về dải Bắc (−z): camYaw π/2 → tới = −z */
270	+  let s = at(map, 100, 17.4);
271	+  for (let i = 0; i < 120; i++) stStep(s, inp({ mz: 1, camYaw: Math.PI / 2 }), map, DT);
272	+  assert.ok(s.z > 16.25, `đi bị gờ chặn, z = ${s.z}`);
273	+  s = at(map, 100, 17.4);
274	+  let crossed = false, jumped = false;
275	+  for (let i = 0; i < 90; i++) {
276	+    stStep(s, inp({ mz: 1, run: true, camYaw: Math.PI / 2, jump: !jumped && i >= 3 }), map, DT);
277	+    if (s.air) jumped = true;
278	+    if (s.z < 15.5) { crossed = true; break; }
279	+  }
280	+  assert.ok(crossed, `chạy + nhảy qua gờ, z = ${s.z}`);
281	+});
282	+
283	+test('đóng cổng shSwing dưới chân: sơ tán về nhịp cố định rồi trả điều khiển', () => {
284	+  const map = makeMap(), s = at(map, 5, SHZ + 3);
285	+  assert.ok(stValid(map, s.x, s.z, 0));
286	+  stSetGate(map, ST_GATE_SWING, true);
287	+  let frames = 0, prev = { x: s.x, z: s.z }, evacSeen = false;
288	+  const dt = 1 / 30;
289	+  while (frames < 300) {
290	+    stStep(s, inp({ mz: -1, camYaw: 0 }), map, dt);   // đầu vào ngược chiều: phải bị bỏ qua khi sơ tán
291	+    const d = Math.hypot(s.x - prev.x, s.z - prev.z);
292	+    assert.ok(d <= C.run * dt + 0.01, `bước ${d}`);
293	+    prev = { x: s.x, z: s.z }; frames++;
294	+    if (s.evac) evacSeen = true;
295	+    if (evacSeen && !s.evac) break;
296	+  }
297	+  assert.ok(evacSeen);
298	+  assert.ok(!s.evac, 'xong sơ tán');
299	+  assert.ok(frames * dt <= 8, `mất ${frames * dt} s`);
300	+  assert.ok(Math.abs(s.x) >= SH.fixedStart - 1e-9, `x = ${s.x}`);
301	+  assert.ok(stValid(map, s.x, s.z, 0));
302	+  for (let i = 0; i < 30; i++) stStep(s, inp({ mz: 1, camYaw: 0 }), map, dt);
303	+  assert.ok(!s.evac && s.speed > 1, 'đầu vào có tác dụng lại');
304	+});
305	+
306	+/* ---- fuzz ---- */
307	+const BRIDGE = new Set(['shSwing', 'songHanW', 'songHanE', 'dragon', 'love']);
308	+function oracle(map: StMap, x: number, z: number): string | null {
309	+  let zone: string | null = null;
310	+  for (const zn of map.zones) {
311	+    if (zn.gate && map.closed.has(zn.gate)) continue;
312	+    if (x >= zn.x0 && x <= zn.x1 && z >= zn.z0 && z <= zn.z1) { zone = zn.id; if (BRIDGE.has(zn.id)) break; }
313	+  }
314	+  if (zone === null) return 'ngoài vùng mở';
315	+  if (!BRIDGE.has(zone) && Math.abs(x) < 262 - R) return 'giữa sông ngoài cầu';
316	+  const B = C.bounds;
317	+  if (x < B.x0 || x > B.x1 || z < B.z0 || z > B.z1) return 'ngoài bounds';
318	+  for (const s of map.solids) {
319	+    if (s.top !== undefined) continue;
320	+    let d: number;
321	+    if (s.kind === 'circle') d = Math.hypot(x - s.cx, z - s.cz) - s.r;
322	+    else { const dx = Math.max(s.x0 - x, 0, x - s.x1), dz = Math.max(s.z0 - z, 0, z - s.z1); d = Math.hypot(dx, dz); }
323	+    if (d < R - 1e-6) return 'gần vật cản cao';
324	+  }
325	+  return null;
326	+}
327	+
328	+test('fuzz 300 000 khung: không lọt tường, không ra khỏi vùng', () => {
329	+  const map = makeMap(), r = rng(99), starts: [number, number][] = [[-240, 17.4], [0, 5], [100, -5], [-100, 3.5], [200, 17], [-5, SHZ + 2], [100, SHZ - 3], [-150, SHZ], [300, SHZ + 1], [250, -78]];
330	+  while (starts.length < 20) {
331	+    const x = (r() * 2 - 1) * 400, z = -1300 + r() * 1520;
332	+    if (stValid(map, x, z, 0) && stGroundY(map, x, z) === stGroundY(map, x, z)) starts.push([x, z]);
333	+  }
334	+  const per = 15000;
335	+  let viol = 0, total = 0, airN = 0, runN = 0;
336	+  for (const [sx, sz] of starts) {
337	+    const s = at(map, sx, sz);
338	+    assert.equal(oracle(map, s.x, s.z), null, `điểm xuất phát ${sx},${sz}`);
339	+    const i2: StInput = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };
340	+    let left = 0;
341	+    for (let f = 0; f < per; f++) {
342	+      if (left <= 0) {
343	+        left = 0.2 + r() * 1.8;
344	+        const a = r() * Math.PI * 2, m = r() < 0.15 ? 0 : 0.3 + 0.7 * r();
345	+        i2.mx = Math.cos(a) * m; i2.mz = Math.sin(a) * m; i2.run = r() < 0.5; i2.camYaw = r() * 6.28 - 3.14; i2.jump = r() < 0.3;
346	+      }
347	+      const dt = 1 / 120 + r() * (0.5 - 1 / 120) * (r() < 0.1 ? 1 : 0.05);
348	+      left -= dt; if (r() < 0.2) i2.jump = r() < 0.3;
349	+      stStep(s, i2, map, dt);
350	+      total++; if (s.air) airN++; if (s.pose === 2) runN++;
351	+      const v = oracle(map, s.x, s.z);
352	+      if (v && viol++ < 5) console.log('vi phạm:', v, s.x, s.z, 'từ', sx, sz, 'khung', f);
353	+    }
354	+  }
355	+  assert.equal(total, 300000);
356	+  assert.ok(airN > 10000 && runN > 10000, `fuzz phải có nhảy và chạy: nhảy ${airN}, chạy ${runN}`);
357	+  assert.equal(viol, 0);
358	+});
