## Diff
diff --git a/src/explore/stroll/motion.ts b/src/explore/stroll/motion.ts
new file mode 100644
index 0000000..14db788
--- /dev/null
+++ b/src/explore/stroll/motion.ts
@@ -0,0 +1,116 @@
+/* ============================ Đi dạo: chuyển động nhân vật (thuần) ============================
+   Mỗi khung: đọc đầu vào, đổi tốc độ / hướng mặt, nhảy, đi qua stMove (va chạm), bám cao độ đứng, chọn dáng (pose).
+   Thuần: không import three, không đụng DOM. stStep chạy mỗi khung nên không cấp phát (D-018): dùng đối tượng tạm cấp module.
+   - dt kẹp về dtMax: khung rất dài (tab ẩn rồi quay lại) không làm nhân vật vọt qua tường, chỉ chậm đi một khung.
+   - Hướng: tới = (cos yaw, 0, −sin yaw), yaw tăng là quay trái (như flight.ts).
+   - Cổng nhịp quay đóng dưới chân (vị trí không còn hợp lệ): stMove đóng băng khi điểm xuất phát không hợp lệ, nên sơ tán KHÔNG dùng stMove:
+     tính một lần điểm hợp lệ gần nhất (stNearestValid, đắt), rồi đi thẳng tới đó với tốc độ chạy, bỏ qua đầu vào; tới nơi thì trả điều khiển. */
+import { CONFIG } from '../../config';
+import { stMove, stValid, stGroundY, stNearestValid, type StMap } from './map';
+import { stSpawn } from './mapData';
+
+export const ST_POSE_IDLE = 0, ST_POSE_WALK = 1, ST_POSE_RUN = 2, ST_POSE_JUMP = 3, ST_POSE_PHOTO = 4;
+
+export interface StState {
+  x: number; y: number; z: number;   // y: cao độ chân tuyệt đối, m
+  yaw: number; speed: number;        // speed: tốc độ mặt bằng, m/s
+  vy: number; air: boolean;          // vy: vận tốc đứng, m/s
+  pose: number; evac: boolean;
+  photo: number;                     // giây còn giơ tay chụp
+  tx: number; tz: number;            // điểm sơ tán đã tính (chỉ có nghĩa khi evac)
+}
+export interface StInput { mx: number; mz: number; run: boolean; jump: boolean; camYaw: number }
+
+const EPS_STEP = 1e-3;      // dung sai khi so bậc cao độ với stepMax (bậc Cầu Rồng lề ↔ bờ đo 0,3500083), m
+const V_STOP = 0.1;         // m/s — dưới mức này coi là đứng yên
+const _mv = { x: 0, z: 0 };      // kết quả stMove
+const _near = { x: 0, z: 0 };    // kết quả stNearestValid
+
+export function stCreate(map: StMap, slot: number): StState {
+  const p = { x: 0, z: 0 };
+  stSpawn(map, slot, p);
+  const g = stGroundY(map, p.x, p.z);
+  return { x: p.x, y: g === g ? g : CONFIG.roadY, z: p.z, yaw: CONFIG.stroll.spawnYaw, speed: 0, vy: 0, air: false, pose: ST_POSE_IDLE, evac: false, photo: 0, tx: p.x, tz: p.z };
+}
+
+export function stPhotoPose(s: StState): void { s.photo = CONFIG.stroll.photoHold; }
+
+/* quay yaw về đích theo đường ngắn nhất, tốc độ mũ turn (1/s) */
+function stTurn(yaw: number, target: number, turn: number, dt: number): number {
+  let d = (target - yaw) % (2 * Math.PI);
+  if (d > Math.PI) d -= 2 * Math.PI; else if (d < -Math.PI) d += 2 * Math.PI;
+  const k = turn * dt;
+  return yaw + d * (k < 1 ? k : 1);
+}
+
+/* Sơ tán: đi thẳng tới (tx, tz) với tốc độ chạy, mỗi khung không quá run × dt */
+function stEvacStep(s: StState, map: StMap, dt: number): void {
+  const C = CONFIG.stroll, dx = s.tx - s.x, dz = s.tz - s.z, dist = Math.sqrt(dx * dx + dz * dz), step = C.run * dt;
+  s.photo = 0; s.speed = C.run; s.pose = ST_POSE_RUN;
+  if (dist > 1e-9) s.yaw = stTurn(s.yaw, Math.atan2(-dz, dx), C.turn, dt);
+  if (dist <= step) { s.x = s.tx; s.z = s.tz; s.evac = false; s.speed = 0; s.pose = ST_POSE_IDLE; }
+  else { s.x += dx / dist * step; s.z += dz / dist * step; }
+  const g = stGroundY(map, s.x, s.z);
+  if (g === g) s.y = g;                                  // ngoài mọi vùng (cổng đóng): giữ cao độ cũ
+  s.air = false; s.vy = 0;
+}
+
+export function stStep(s: StState, inp: StInput, map: StMap, dt: number): void {
+  const C = CONFIG.stroll;
+  if (!(dt > 0)) return;
+  if (dt > C.dtMax) dt = C.dtMax;
+
+  /* 1) vị trí không còn hợp lệ với tường cao / vùng (tường thấp không tính: đáp xuống giữa tường thấp là chuyện của stMove) */
+  if (!s.evac && !stValid(map, s.x, s.z, Infinity)) {
+    s.evac = true;
+    if (!stNearestValid(map, s.x, s.z, _near)) stSpawn(map, -1, _near);
+    s.tx = _near.x; s.tz = _near.z;
+  }
+  if (s.evac) { stEvacStep(s, map, dt); return; }
+
+  /* 2) hướng đi và tốc độ đích */
+  const sc = Math.sin(inp.camYaw), cc = Math.cos(inp.camYaw);
+  const dx = inp.mz * cc + inp.mx * sc, dz = -inp.mz * sc + inp.mx * cc;
+  let len = Math.sqrt(dx * dx + dz * dz);
+  const moving = len > 1e-6;
+  if (len > 1) len = 1;
+  const target = moving ? (inp.run ? C.run : C.walk) * len : 0;
+  const da = C.accel * dt;
+  if (s.speed < target) s.speed = s.speed + da < target ? s.speed + da : target;
+  else s.speed = s.speed - da > target ? s.speed - da : target;
+  let hx: number, hz: number;                            // hướng di chuyển: theo đầu vào; thả tay thì trượt theo hướng mặt đang hãm
+  if (moving) { hx = dx / Math.sqrt(dx * dx + dz * dz); hz = dz / Math.sqrt(dx * dx + dz * dz); s.yaw = stTurn(s.yaw, Math.atan2(-hz, hx), C.turn, dt); }
+  else { hx = Math.cos(s.yaw); hz = -Math.sin(s.yaw); }
+
+  /* 3) nhảy: chỉ khi chạm đất */
+  if (!s.air && inp.jump) { s.vy = Math.sqrt(2 * C.gravity * C.jumpHeight); s.air = true; }
+
+  /* 4) đi (feet: độ cao chân trên cao độ đứng chỗ đang đứng) */
+  const g0 = stGroundY(map, s.x, s.z);
+  const feet = s.air && g0 === g0 ? Math.max(0, s.y - g0) : 0;
+  const dist = s.speed * dt;
+  stMove(map, s.x, s.z, hx * dist, hz * dist, feet, _mv);
+  s.x = _mv.x; s.z = _mv.z;
+
+  /* 5) cao độ */
+  const g = stGroundY(map, s.x, s.z);
+  if (s.air) {
+    const ny = s.y + s.vy * dt - 0.5 * C.gravity * dt * dt;
+    s.vy -= C.gravity * dt;
+    if (g === g && ny <= g) {                            // chạm đất
+      s.y = g; s.vy = 0; s.air = false;
+      if (!stValid(map, s.x, s.z, 0) && stNearestValid(map, s.x, s.z, _near)) { s.x = _near.x; s.z = _near.z; const g2 = stGroundY(map, s.x, s.z); if (g2 === g2) s.y = g2; }   // đáp giữa tường thấp: đẩy ra mép gần nhất
+    } else s.y = ny;
+  } else if (g === g) {
+    if (s.y - g > C.stepMax + EPS_STEP) { s.air = true; s.vy = 0; }   // bước xuống quá bậc: rơi
+    else s.y = g;
+  }
+
+  /* 6) dáng */
+  if (s.photo > 0) { if (moving || s.air) s.photo = 0; else { s.photo -= dt; if (s.photo < 0) s.photo = 0; } }
+  const still = s.speed < V_STOP && !moving;
+  if (s.air) s.pose = ST_POSE_JUMP;
+  else if (s.photo > 0 && still) s.pose = ST_POSE_PHOTO;
+  else if (s.speed < V_STOP) s.pose = ST_POSE_IDLE;
+  else s.pose = s.speed > (C.walk + C.run) * 0.5 ? ST_POSE_RUN : ST_POSE_WALK;
+}
diff --git a/tests/stroll-unit/motion.test.ts b/tests/stroll-unit/motion.test.ts
new file mode 100644
index 0000000..e859f4a
--- /dev/null
+++ b/tests/stroll-unit/motion.test.ts
@@ -0,0 +1,219 @@
+/* ===== Đi dạo: test chuyển động nhân vật (src/explore/stroll/motion.ts) =====
+   Bản đồ thật (stBuildStaticMap) cộng 300 nhà chữ nhật giả sinh bằng rng trong hai vùng bờ. Fuzz 300 000 khung kiểm điểm cuối bằng oracle viết riêng ở đây
+   (quét tuyến tính mọi vùng / vật cản cao, không dùng lưới của map.ts). */
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { CONFIG } from '../../src/config.ts';
+import { rng } from '../../src/common/math.ts';
+import { deckY } from '../../src/bridges/dragon/profile.ts';
+import { SH } from '../../src/bridges/song-han/profile.ts';
+import { stValid, stSetGate, stAddSolids, stGroundY, type StMap, type StSolid } from '../../src/explore/stroll/map.ts';
+import { ST_GATE_SWING, stBuildStaticMap, stSpawn } from '../../src/explore/stroll/mapData.ts';
+import { stCreate, stStep, stPhotoPose, type StState, type StInput } from '../../src/explore/stroll/motion.ts';
+
+const C = CONFIG.stroll, R = C.radius, SHZ = CONFIG.songHan.z;
+const DT = 1 / 60;
+
+/* bản đồ có nhà giả: mỗi lần gọi dựng mới (cổng đóng / mở không dây sang test khác) */
+function makeMap(): StMap {
+  const map = stBuildStaticMap();
+  const r = rng(4242), sp = { x: 0, z: 0 }, houses: StSolid[] = [];
+  stSpawn(map, -1, sp);
+  for (let i = 0; i < 300; i++) {
+    const west = r() < 0.5, x0 = (west ? -1 : 1) * (270 + r() * 120), z0 = -1290 + r() * 1500, w = 8 + r() * 30, d = 8 + r() * 30;
+    const h: StSolid = { kind: 'rect', x0: west ? x0 - w : x0, x1: west ? x0 : x0 + w, z0, z1: z0 + d };
+    if (h.z1 > -22 && h.z0 < 22 || h.z1 > SHZ - 10 && h.z0 < SHZ + 10) continue;   // nhà thật không đè đường nối cầu
+    if (sp.x > h.x0 - 3 && sp.x < h.x1 + 3 && sp.z > h.z0 - 3 && sp.z < h.z1 + 3) continue;   // bỏ nhà đè điểm xuất phát
+    houses.push(h);
+  }
+  stAddSolids(map, houses);
+  return map;
+}
+const IDLE: StInput = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };
+const inp = (o: Partial<StInput>): StInput => ({ ...IDLE, ...o });
+function at(map: StMap, x: number, z: number): StState {
+  const s = stCreate(map, -1); s.x = x; s.z = z; s.y = stGroundY(map, x, z); return s;
+}
+
+test('đi thẳng 10 s: đi 3,5 m/s, chạy 10 m/s', () => {
+  for (const run of [false, true]) {
+    const map = makeMap(), s = stCreate(map, -1), x0 = s.x;
+    for (let i = 0; i < 600; i++) stStep(s, inp({ mz: 1, run }), map, DT);
+    const v = run ? C.run : C.walk;
+    assert.ok(Math.abs(s.speed - v) <= (run ? 0.1 : 0.05), `tốc độ ${s.speed}`);
+    assert.ok(Math.abs(s.x - x0 - 10 * v) <= (run ? 2 : 1.5), `quãng đường ${s.x - x0}`);
+  }
+});
+
+test('hướng theo camYaw', () => {
+  const map = makeMap();
+  let s = at(map, 0, 17.4);
+  for (let i = 0; i < 30; i++) stStep(s, inp({ mz: 1, camYaw: 0 }), map, DT);
+  assert.ok(s.x > 1 && Math.abs(s.z - 17.4) < 0.01, 'camYaw 0, tới → x tăng');
+  s = at(map, 0, 0 + 3.5);   // dải phân cách có thân rồng chỉ ở đầu / cuối: x = 0 trống
+  const z0 = s.z;
+  for (let i = 0; i < 30; i++) stStep(s, inp({ mz: 1, camYaw: Math.PI / 2 }), map, DT);
+  assert.ok(s.z < z0 - 1, 'camYaw π/2, tới → z giảm');
+  s = at(map, 0, 17.4); const z1 = s.z;
+  for (let i = 0; i < 30; i++) stStep(s, inp({ mx: 1, camYaw: 0 }), map, DT);
+  assert.ok(s.z > z1 + 0.1, 'camYaw 0, sang phải → z tăng (lề hẹp, bị lan can chặn)');
+  s = at(map, 0, 5); const z2 = s.z;
+  for (let i = 0; i < 30; i++) stStep(s, inp({ mx: 1, camYaw: 0 }), map, DT);
+  assert.ok(s.z > z2 + 1, 'camYaw 0, sang phải → z tăng (chỗ rộng)');
+});
+
+test('nhảy: đỉnh 1,2 m, pose 3 trên không, giữ nút không nhảy lần hai', () => {
+  const map = makeMap(), s = at(map, 0, 5), g = s.y;
+  let peak = 0, airFrames = 0, landed = -1;
+  for (let i = 0; i < 120; i++) {
+    stStep(s, inp({ jump: true }), map, 1 / 120);
+    peak = Math.max(peak, s.y - g);
+    if (s.air) { airFrames++; assert.equal(s.pose, 3); }
+    else if (landed < 0 && i > 2) landed = i;
+  }
+  assert.ok(Math.abs(peak - C.jumpHeight) <= 0.05, `đỉnh ${peak}`);
+  assert.ok(airFrames > 0);
+  /* một cú nhảy: thời gian bay = 2 v / g ≈ 0,69 s = 83 khung; sau đó (còn giữ) mới nhảy lần nữa, không có đỉnh thứ hai trước khi chạm */
+  const s2 = at(map, 0, 5); let rises = 0, prevVy = 0, hit = false;
+  for (let i = 0; i < 80; i++) {
+    stStep(s2, inp({ jump: true }), map, 1 / 120);
+    if (s2.vy > prevVy + 1e-9) rises++;
+    prevVy = s2.vy; if (!s2.air) hit = true;
+  }
+  assert.equal(rises, 1, 'vy chỉ tăng đúng một lần (lúc bật)');
+  assert.ok(!hit, 'chưa chạm đất trong 80 khung 1/120 s');
+});
+
+test('cao độ: đi dọc Cầu Rồng bám mặt cầu + bậc', () => {
+  const map = makeMap(), s = at(map, -300, 17.4);
+  let worst = 0, minx = s.x;
+  for (let i = 0; i < 6000 && s.x < 300; i++) {
+    stStep(s, inp({ mz: 1, run: true }), map, DT);
+    const ground = stGroundY(map, s.x, s.z);
+    worst = Math.max(worst, Math.abs(s.y - ground));
+    assert.ok(Math.abs(s.y - (deckY(s.x) + (Math.abs(s.z) <= 3 ? 0.3 : Math.abs(s.z) < 16.075 ? 0.02 : 0.25))) <= 0.02, `x=${s.x}`);
+  }
+  assert.ok(s.x >= 300, `đi tới x ${s.x}`);
+  assert.ok(worst <= 0.02);
+});
+
+test('pose: 0 đứng, 1 đi, 2 chạy, 4 chụp ảnh rồi hết photoHold về 0', () => {
+  const map = makeMap(), s = at(map, 0, 17.4);
+  stStep(s, IDLE, map, DT); assert.equal(s.pose, 0);
+  for (let i = 0; i < 40; i++) stStep(s, inp({ mz: 1 }), map, DT);
+  assert.equal(s.pose, 1);
+  for (let i = 0; i < 60; i++) stStep(s, inp({ mz: 1, run: true }), map, DT);
+  assert.equal(s.pose, 2);
+  for (let i = 0; i < 60; i++) stStep(s, IDLE, map, DT);
+  assert.equal(s.pose, 0);
+  stPhotoPose(s); assert.equal(s.photo, C.photoHold);
+  stStep(s, IDLE, map, DT); assert.equal(s.pose, 4);
+  for (let i = 0; i < Math.ceil(C.photoHold / DT) + 2; i++) stStep(s, IDLE, map, DT);
+  assert.equal(s.pose, 0); assert.equal(s.photo, 0);
+});
+
+test('dt = 2 s lúc chạy vào lan can Cầu Rồng: không vọt xa, không lọt', () => {
+  const map = makeMap(), s = at(map, 0, 17.4);
+  for (let i = 0; i < 60; i++) stStep(s, inp({ mx: 1, run: true, camYaw: 0 }), map, DT);   // chạy sang phải = +z, tới lan can phía Nam
+  const before = { x: s.x, z: s.z };
+  stStep(s, inp({ mx: 1, run: true }), map, 2);
+  assert.ok(Math.hypot(s.x - before.x, s.z - before.z) <= C.run * C.dtMax + 0.01);
+  assert.ok(stValid(map, s.x, s.z, 0));
+  /* chạy thẳng dọc, rồi một khung 2 s đâm vào mép đầu cầu: vẫn hợp lệ */
+  const t = at(map, 0, 17.4);
+  for (let i = 0; i < 90; i++) stStep(t, inp({ mz: 1, run: true, camYaw: 0 }), map, DT);
+  for (let k = 0; k < 5; k++) { const p = { x: t.x, z: t.z }; stStep(t, inp({ mz: 1, mx: 1, run: true, camYaw: 0 }), map, 2); assert.ok(Math.hypot(t.x - p.x, t.z - p.z) <= C.run * C.dtMax + 0.01); assert.ok(stValid(map, t.x, t.z, Infinity)); }
+});
+
+test('gờ chắn xe Cầu Rồng: đi ngang bị chặn, chạy + nhảy thì qua', () => {
+  const map = makeMap();
+  /* từ lề Nam (z 17,4) đi về dải Bắc (−z): camYaw π/2 → tới = −z */
+  let s = at(map, 100, 17.4);
+  for (let i = 0; i < 120; i++) stStep(s, inp({ mz: 1, camYaw: Math.PI / 2 }), map, DT);
